npcHandler:setCallback(CALLBACK_MESSAGE_DEFAULT, function(npc, player, type, msg)
	if SpireHunt and MsgContains(msg, "hunt") then
		npcHandler:say(SpireHunt.advice(player:getLevel()), npc, player)
		return false
	end
	return true
end)
